sible",\r\n          "action": "wait",\r\n          "description": "等待上传附件对话框显示",\r\n          "until": {\r\n            "type": "selector_visible",\r\n            "selector": "//div[@role=\'dialog\' and contains(., \'上传附件\')]"\r\n          },\r\n          "timeout": 10000\r\n        },\r\n        {\r\n          "kind": "step",\r\n          "name": "pause_500ms_035",\r\n          "action": "wait",\r\n          "ms": 500,\r\n          "description": "固定等待500ms（waitAttachmentDialogVisible之后）"\r\n        },\r\n        {\r\n          "kind": "step",\r\n          "name": "uploadFiles",\r\n          "action": "upload",\r\n          "selector": "//div[contains(@class,\'el-upload\')]//input[@type=\'file\' and @name=\'file\']",\r\n          "filePath": "{{attachments}}",\r\n          "field": "attachments",\r\n          "description": "使用upload action一次上传所有附件"\r\n        },\r\n        {\r\n          "kind": "step",\r\n          "name": "pause_500ms_036",\r\n          "action": "wait",\r\n          "ms": 500,\r\n          "description": "固定等待1500ms（uploadFiles之后）"\r\n        },\r\n        {\r\n          "kind": "step",\r\n          "name": "clickSaveAttachment",\r\n          "action": "click",\r\n          "selector": "//div[contains(@class,\'el-dialog__wrapper\')][not(contains(@style,\'display: none\'))]//div[@role=\'dialog\'][@aria-label=\'上传附件\']//div[contains(@class,\'upload\')]//button[contains(@class,\'el-button--primary\')][.//span[normalize-space()=\'保存\']]",\r\n          "description": "点击上传附件dialog内div.upload区的保存按钮（保存按钮在body的右对齐div内，非footer）"\r\n        },\r\n        {\r\n          "kind": "step",\r\n          "name": "pause_500ms_037",\r\n          "action": "wait",\r\n          "ms": 500,\r\n          "description": "固定等待500ms（clickSaveAttachment之后）"\r\n        },\r\n        {\r\n          "kind": "step",\r\n          "name": "waitAttachmentDialogClose",\r\n          "action": "wait",\r\n          "description": "等待上传附件dialog关闭（aria-label=上传附件的可见wrapper消失）",\r\n  